ALTER TABLE salud_u.solicitud_cita DROP CONSTRAINT cita_solicitud_type;
ALTER TABLE salud_u.solicitud_cita ADD COLUMN id_especialidad uuid NULL REFERENCES salud_u.especialidad(id) ON DELETE RESTRICT;
ALTER TABLE salud_u.solicitud_cita ADD COLUMN origin text NOT NULL DEFAULT 'INITIAL';
ALTER TABLE salud_u.solicitud_cita ADD CONSTRAINT cita_solicitud_type CHECK ((tipo_cita='INITIAL' AND id_especialidad IS NULL AND origin='INITIAL') OR (tipo_cita='SPECIALTY' AND id_especialidad IS NOT NULL AND origin='ADMIN_DIRECT'));
CREATE UNIQUE INDEX cita_solicitud_one_pending_especialidad ON salud_u.solicitud_cita(id_paciente,id_especialidad) WHERE estado='PENDING' AND tipo_cita='SPECIALTY';
CREATE FUNCTION salud_u.crear_solicitud_especialidad_directa(p_paciente_id uuid,p_especialidad_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ DECLARE solicitud_id uuid; BEGIN PERFORM salud_u.requerir_administrativo(); IF NOT EXISTS(SELECT 1 FROM salud_u.paciente WHERE id=p_paciente_id AND archivado_en IS NULL) THEN RAISE EXCEPTION 'Paciente no encontrado' USING ERRCODE='P0002'; END IF; IF NOT EXISTS(SELECT 1 FROM salud_u.especialidad WHERE id=p_especialidad_id AND activo) THEN RAISE EXCEPTION 'La especialidad no está activa' USING ERRCODE='23514'; END IF; INSERT INTO salud_u.solicitud_cita(id_paciente,tipo_cita,id_especialidad,origin,solicitado_por) VALUES(p_paciente_id,'SPECIALTY',p_especialidad_id,'ADMIN_DIRECT',salud_u.id_actor_actual()) RETURNING id INTO solicitud_id; RETURN solicitud_id; END; $$;
REVOKE ALL ON FUNCTION salud_u.crear_solicitud_especialidad_directa(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION salud_u.crear_solicitud_especialidad_directa(uuid,uuid) TO ${runtime_role};
